// One-off check for AC3: with discount 0, the fixed total() equals the pre-fix total() for every sampled cart.
import { total as oldTotal } from './cart.old.js';
import { total as newTotal } from '../../src/cart.js';

let seed = 12;
const rnd = () => (seed = (seed * 1664525 + 1013904223) >>> 0) / 2 ** 32;
let checked = 0, diff = 0;
const cmp = (items, ...args) => {
  checked++;
  const a = oldTotal(items, ...args), b = newTotal(items, ...args);
  if (!Object.is(a, b)) { diff++; if (diff <= 5) console.log('DIFF', JSON.stringify(items), args, a, b); }
};
for (let i = 0; i < 200000; i++) {
  const n = Math.floor(rnd() * 25); // 0..24 lines, both sides of the 10-line boundary
  const items = Array.from({ length: n }, () => ({ price: Math.floor(rnd() * 100000), qty: 1 + Math.floor(rnd() * 20) }));
  cmp(items, 0);   // explicit 0
  cmp(items);      // default
}
// exhaustive small subtotals on both sides of the boundary (covers every x.5 rounding case of subtotal*0.95)
for (let s = 0; s <= 100000; s++) {
  cmp([{ price: s, qty: 1 }], 0);
  cmp([{ price: s, qty: 1 }, ...Array.from({ length: 9 }, () => ({ price: 0, qty: 1 }))], 0);
}
console.log(`checked=${checked} different=${diff}`);
// sanity: the comparison can detect a difference (discount 0.1 must differ between old and new)
