import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// n lines of `price` each, qty 1.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('customer discount is applied once (issue #12)', () => {
  // 1,000 less 10% = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('10 or more lines: 5% bulk discount once, after the customer discount (issue #12)', () => {
  // 10,000 less 10% = 9,000, less 5% = 8,550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('fewer than 10 lines: customer discount only, no bulk discount (issue #12)', () => {
  // 9,000 less 10% = 8,100
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('discount rate 0: only the bulk discount applies (issue #12)', () => {
  assert.equal(total(lines(9, 1000), 0), 9000);
  // 10,000 less 5% = 9,500
  assert.equal(total(lines(10, 1000), 0), 9500);
  // 907 less 5% = 861.65, rounded to 862
  assert.equal(total([...lines(9, 100), { price: 7, qty: 1 }], 0), 862);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
